package com.codexpane.companion;

import org.junit.Test;
import static org.junit.Assert.*;

public class NativeUpdatePolicyTest {
    @Test public void acceptsOnlyNamedRepositoryReleaseApks(){assertTrue(NativeUpdatePolicy.androidAsset("https://github.com/kismet84/paneflow/releases/download/v0.7.0/PaneFlow-0.7.0.apk"));assertFalse(NativeUpdatePolicy.androidAsset("https://github.com/other/paneflow/releases/download/v0.7.0/app.apk"));assertFalse(NativeUpdatePolicy.androidAsset("https://github.com/kismet84/paneflow/releases/latest/download/app.apk"));assertFalse(NativeUpdatePolicy.androidAsset("https://github.com/kismet84/paneflow/releases/download/v0.7.0/setup.exe"));}
    @Test public void blocksPlaintextCredentialsQueriesAndEncodedTraversal(){for(String value:new String[]{"http://github.com/kismet84/paneflow/releases/download/v1/app.apk","https://user@github.com/kismet84/paneflow/releases/download/v1/app.apk","https://github.com/kismet84/paneflow/releases/download/v1/app.apk?redirect=evil","https://github.com/kismet84/paneflow/releases/download/v1/%2e%2e%2fapp.apk","https://github.com/kismet84/paneflow/releases/download/../app.apk","https://github.com.evil.test/kismet84/paneflow/releases/download/v1/app.apk"})assertFalse(value,NativeUpdatePolicy.androidAsset(value));}
    @Test public void permitsOnlyFixedManifestAndGithubAssetRedirectHosts(){assertTrue(NativeUpdatePolicy.fetchUrl(NativeUpdatePolicy.MANIFEST_URL));assertTrue(NativeUpdatePolicy.fetchUrl("https://release-assets.githubusercontent.com/github-production-release-asset/12/abc?sig=abc"));assertTrue(NativeUpdatePolicy.fetchUrl("https://objects.githubusercontent.com/github-production-release-asset-2e65be/12/abc?sig=abc"));assertFalse(NativeUpdatePolicy.fetchUrl("https://release-assets.githubusercontent.com.evil.test/github-production-release-asset/12/abc"));assertFalse(NativeUpdatePolicy.fetchUrl("https://raw.githubusercontent.com/kismet84/paneflow/main/update.json"));assertFalse(NativeUpdatePolicy.fetchUrl("https://release-assets.githubusercontent.com/other/path"));assertFalse(NativeUpdatePolicy.fetchUrl("http://release-assets.githubusercontent.com/github-production-release-asset/12/abc"));}
}
